import{_ as n,a as t,b as i,c as r}from"./chunks/solar-solo-ports.BXO9gIDw.js";import{_ as s,o as a,c as o,a3 as d}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Solar – Wechselrichter und stapelbare Akkus","description":"Neutrale SVG-Module mit bündigen Gehäusekoppelpunkten, Textanzeigen und frei zugeordneten Datenflussanschlüssen.","frontmatter":{"title":"Solar – Wechselrichter und stapelbare Akkus","description":"Neutrale SVG-Module mit bündigen Gehäusekoppelpunkten, Textanzeigen und frei zugeordneten Datenflussanschlüssen."},"headers":[],"relativePath":"projects/grafik-visual-studio/solar.md","filePath":"projects/grafik-visual-studio/solar.md","lastUpdated":1792851046000}'),u={name:"projects/grafik-visual-studio/solar.md"};function l(g,e,h,p,c,b){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="solar" tabindex="-1">Solar <a class="header-anchor" href="#solar" aria-label="Permalink to &quot;Solar&quot;">​</a></h1><p><strong>Solar 0.1.3</strong> benötigt <strong>Studio 0.1.280 oder neuer</strong>. Das eigenständige Widgetset enthält vier markenunabhängige Module mit transparenten SVG-Grafiken. Aktualisiere zuerst Studio und importiere danach die <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/raw/refs/heads/master/ha_grafik_visual_studio/packages/solar/ugso.solar.wg" target="_blank" rel="noreferrer">Paketdatei ugso.solar.wg</a> über die Paketeinstellungen.</p><table tabindex="0"><thead><tr><th>Widget</th><th>Standardgröße</th><th>Gehäusekoppelpunkte</th><th>Linienpunkte</th></tr></thead><tbody><tr><td>Stapel-Kopfteil</td><td>256 × 64 px</td><td>Unten mittig</td><td>Links/rechts sowie je zwei Solarpanel-Eingänge an beiden Gehäuseseiten</td></tr><tr><td>Batteriemodul</td><td>256 × 169 px</td><td>Oben und unten mittig</td><td>Links, rechts</td></tr><tr><td>Wechselrichter Solo</td><td>144 × 103,3 px</td><td>Keine</td><td>Links/rechts/oben mittig sowie sieben Punkte unten inklusive Ecken</td></tr><tr><td>Solarpanel mit Standfuß</td><td>320 × 288 px</td><td>Keine</td><td>Ein Ausgang: Standrohr oder Widgetkante links/rechts</td></tr></tbody></table><p>Die Kopfteilgrafik sitzt mittig auf der unteren Widgetkante. Die Batterie schließt mit der Grafik oben und unten bündig ab. Batterie und Solo behalten beim Vergrößern oder Verkleinern ihre Proportionen. Das sichtbare Solo-Gehäuse ist etwa ein Drittel schmaler als das Kopfteil.</p><p><img src="'+n+'" alt="Solar im Editor: Batteriestapel, Solo-Wechselrichter und beide Solarpanel-Ausrichtungen"></p><p>Beispiel mit Vorschauwerten und eingeblendeten Anschlusspunkten. Gelbe Kreise sind Eingänge, blaue Kreise Ausgänge und violette Quadrate Gehäusekoppelpunkte. In der Runtime verschwinden die Punkte.</p><h2 id="solarpanel-mit-standrohr-und-fuß" tabindex="-1">Solarpanel mit Standrohr und Fuß <a class="header-anchor" href="#solarpanel-mit-standrohr-und-fuß" aria-label="Permalink to &quot;Solarpanel mit Standrohr und Fuß&quot;">​</a></h2><p>Unter <strong>Solar-Modul → Ausrichtung</strong> wählst du <strong>Wie Vorlage</strong> oder <strong>Gespiegelt</strong>. Die SVG-Grafik wird horizontal gespiegelt; Schrift und Wertanzeige bleiben lesbar. Beim Skalieren bleiben die Proportionen erhalten.</p><p><img src="'+t+'" alt="Solarpanel mit Standrohr und Fuß: links wie Vorlage, rechts gespiegelt, Ausgang jeweils am Standrohr"></p><p>Wähle unter <strong>Leistung → Eingangsentität (Leistung)</strong> eine Home-Assistant-Entität. Werte in kW werden in W umgerechnet. <strong>Wert anzeigen</strong> blendet nur den rahmenlosen Text aus; der Ausgang liefert weiter Daten. Ohne Entität gilt der Vorschauwert, bei unbekannter Entität erscheint ein Strich.</p><p>Unter <strong>Linienanschluss → Position des Ausgangspunkts</strong> stehen drei Positionen zur Wahl: <strong>Am Standrohr über dem Fuß</strong>, <strong>Widgetkante links</strong> und <strong>Widgetkante rechts</strong>. Die Kantenpositionen liegen auf gleicher Höhe wie der Punkt am Rohr. Es bleibt genau ein Ausgang; bereits angeschlossene SVG-Linien folgen beim Umstellen automatisch. <strong>Ausgangspunkt aktiv</strong> schaltet ihn ab oder an. In der Runtime ist der Punkt unsichtbar, die SVG-Linie bleibt sichtbar. Das Solarpanel hat keine Gehäusekoppelpunkte.</p><h2 id="einen-stapel-zusammensetzen" tabindex="-1">Einen Stapel zusammensetzen <a class="header-anchor" href="#einen-stapel-zusammensetzen" aria-label="Permalink to &quot;Einen Stapel zusammensetzen&quot;">​</a></h2><p>Füge <strong>ein Kopfteil</strong> und je nach Anlage <strong>1–6 Instanzen desselben Batterie-Widgets</strong> hinzu. Jede Batterie hat eigene Einstellungen und Entitäten. Die mittigen Gehäusekoppelpunkte sind standardmäßig aktiviert, mit Abstand <strong>0 px</strong>. Ziehe eine Batterie mit ihrem oberen Punkt an den unteren Punkt des Kopfteils oder einer anderen Batterie. Die Teile rasten bündig und mittig ein.</p><p>Unter <strong>Gehäuse-Snappunkte</strong> lassen sich Snapping, einzelne Punkte, Abstand und dauerhafte Editoranzeige einstellen. Gehäusekoppelpunkte dienen nur der Platzierung; sie übertragen keine Werte. Die Punkte sind in der Runtime unsichtbar.</p><h2 id="werte-als-text-auf-dem-gehause" tabindex="-1">Werte als Text auf dem Gehäuse <a class="header-anchor" href="#werte-als-text-auf-dem-gehause" aria-label="Permalink to &quot;Werte als Text auf dem Gehäuse&quot;">​</a></h2><p>Für <strong>Leistung</strong>, <strong>Temperatur</strong> und <strong>Ladezustand (SoC)</strong> gibt es jeweils eine Home-Assistant-Entitätsauswahl und einen Vorschauwert. Die Einheiten sind <strong>W</strong>, <strong>°C</strong> und <strong>%</strong>. Leistung aus einer kW-Entität wird in W umgerechnet. Ein Vorschauwert gilt nur, solange keine Entität eingetragen ist. Fehlende oder unbekannte Zustände erscheinen als <strong>—</strong>.</p><p><strong>Wert anzeigen</strong> schaltet ausschließlich die jeweilige Textanzeige ab. Die Entität wird weiterhin aktualisiert, und Ausgänge liefern weiterhin ihren Wert. Bei der Batterie beginnen die aktiven Anzeigen direkt unter der Trennlinie nach dem ersten Drittel und stehen automatisch untereinander, ohne Leerzeilen für ausgeblendete Werte. Es gibt keine Rahmen oder Anzeigekästchen. Die Reihenfolge ist Leistung, Temperatur, SoC. Schriftfarbe und maximale Schriftgröße sind einstellbar; bei wenig Platz wird die Schrift verkleinert.</p><p>Standardmäßig zeigt die Batterie alle drei Werte und Solo nur die Leistung. Das Kopfteil zeigt keine Werte und bietet keine Gruppen für Leistung, Temperatur, SoC oder Leistungsrichtung. Beim Solo-Wechselrichter bleiben diese Einstellungen erhalten.</p><p>Bei der Batterie lässt sich unter <strong>Leistung</strong>, <strong>Temperatur</strong> und <strong>Ladezustand (SoC)</strong> jeweils die <strong>Schriftfarbe des Werts</strong> getrennt einstellen. Ohne eigene Farbe gilt die allgemeine Schriftfarbe. Die Farbe bleibt auch beim Aus- und Wiedereinblenden der Anzeige erhalten.</p><p><img src="'+i+'" alt="Stapel-Kopfteil mit vier Solarpanel-Eingängen und Batterie mit farbigen Werten sowie seitlichen Linienpunkten an der unteren Naht"></p><p>Unter <strong>Leistungsrichtung</strong> kannst du ein Richtungssymbol zuschalten. Lege fest, ob positive Leistung <strong>Energie hinein</strong> oder <strong>Energie heraus</strong> bedeutet, und wähle die beiden Symbole über freie Texteingaben. Bei Leistung 0 oder einem unbekannten Wert wird kein Richtungssymbol gezeigt. Das Vorzeichen des Zahlenwerts bleibt erhalten.</p><h2 id="ein-und-ausgange-fur-svg-linien" tabindex="-1">Ein- und Ausgänge für SVG-Linien <a class="header-anchor" href="#ein-und-ausgange-fur-svg-linien" aria-label="Permalink to &quot;Ein- und Ausgänge für SVG-Linien&quot;">​</a></h2><p>Der <strong>Solo-Wechselrichter</strong> bietet an der Unterkante sieben gleichmäßig verteilte Linienpunkte: die beiden Ecken, den bisherigen Mittelpunkt und je zwei weitere Punkte links/rechts davon. Zusammen mit links/rechts/oben mittig sind zehn Linienpunkte möglich. Unter <strong>Linienanschlüsse</strong> stellst du pro Punkt <strong>Aus</strong>, <strong>Eingang</strong> oder <strong>Ausgang</strong> und den Wert ein. Die sechs neuen unteren Punkte sind zunächst aus; vorhandene Anschlüsse und Verbindungen bleiben erhalten.</p><p><img src="'+r+'" alt="Solo-Wechselrichter mit sieben Linienpunkten unten und drei weiteren Punkten links, rechts und oben"></p><p>Für dieses Beispiel sind alle zehn Punkte als Ausgang aktiviert; im eigenen Projekt ist die Rolle pro Punkt wählbar.</p><p>Bei der Batterie gibt es links und rechts zusätzlich eine <strong>Position</strong>: <strong>Widgetkante Mitte</strong> oder <strong>Gehäusekante an unterer Naht</strong>. Beide Seiten lassen sich unabhängig umstellen. Vorhandene Verbindungen folgen automatisch; Ein-/Ausgangsrolle und Wertzuordnung bleiben erhalten. Die mittigen Gehäusekoppelpunkte oben/unten für das Stapeln ändern sich dadurch nicht.</p><p>Das Kopfteil besitzt vier optische Solarpanel-Anschlussbuchsen: links oben/unten und rechts oben/unten. Diese vier Eingänge sind standardmäßig aktiv und unter <strong>Linienanschlüsse</strong> einzeln abschaltbar. Sie folgen der unten bündigen Grafik auch bei anderer Widgethöhe. Verbinde die SVG-Linie eines Solarpanels mit einer solchen Buchse. Die Eingänge sind getrennte Linienziele; Werte werden nicht automatisch summiert. Der frühere obere Linienanschluss entfällt; die bisherigen linken/rechten Linienpunkte bleiben verfügbar.</p><p>Unter <strong>Linienanschlüsse</strong> hat jede verfügbare Seite zwei Einstellungen:</p><ul><li><strong>Rolle:</strong> Aus, Eingang oder Ausgang. Standardmäßig sind die Linienpunkte aus.</li><li><strong>Wert:</strong> Leistung, Temperatur oder Ladezustand (SoC).</li></ul><p>Ein <strong>Ausgang</strong> gibt den ausgewählten Wert mit Einheit weiter, zum Beispiel an Number oder an eine SVG-Linie. Ein <strong>Eingang</strong> übernimmt diesen Wert aus genau einer angeschlossenen Quelle und ersetzt für diesen Kanal die Entität. Verwende höchstens einen Eingang pro Wert. Ein anderer Ausgang kann den übernommenen Wert weiterreichen; Rückkopplungen werden abgefangen. Es werden keine Home-Assistant-Entitäten beschrieben.</p><p>Die Linienpunkte sind unabhängig von den Gehäusekoppelpunkten. Aktive Ausgänge nutzen die Ausgangspunktfarbe aus den Studio-Einstellungen. In der Runtime verschwinden die Punkte; normale SVG-Linien bleiben sichtbar, Wert-Verbindungen bleiben unsichtbar.</p><p>Alle Standard-CSS-Gruppen sind verfügbar; die optionalen Bereiche sind zunächst ausgeschaltet. Eigene Innenabstände und Rahmen können die bündige Darstellung verändern.</p><p>Die SVGs sind eigene UGSo-Grafiken ohne Herstellerlogo. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/solar" target="_blank" rel="noreferrer">Quellcode, Bauanleitung und MIT-Lizenz</a>.</p>',33)])])}const S=s(u,[["render",l]]);export{f as __pageData,S as default};
